/**
 * Model Aquarium
 * cthulhuquarium/t-007: a player's persistent tank. Fish species are
 * Monster rows -- AquariumStock references them, never duplicates them.
 * See projects/cthulhuquarium/roadmap.yaml and DESIGN-BRIEF.md in conductor.
 */
export type Aquarium = Prisma.AquariumModel
/**
 * Model AquariumStock
 * One fish (Monster row) placed in one Aquarium. hunger/mood are the live
 * play-loop state; placedAt lets the UI order a tank by arrival.
 * 
 * cthulhuquarium/t-032: the bible (Character) describes species; this table
 * contains individuals. Two goldfish are the same Character row and
 * different AquariumStock rows -- hidden stats and parentage live here,
 * never on Character, so the bible stays a catalogue rather than a save
 * file. See SYSTEMS.md "Genetics: hidden stats, breeding, and secret
 * evolutions".
 */
export type AquariumStock = Prisma.AquariumStockModel
/**
 * Model AquariumSet
 * cthulhuquarium/t-032 item 3: a set piece equipped in one Aquarium, counted
 * against Aquarium.setSlotsCap -- a distinct pool from fish (AquariumStock),
 * which is weighed by size instead of counted. `kind` keys into
 * projects/cthulhuquarium/data/economy.yaml's `set_pieces` catalogue (e.g.
 * "extra_species_slot", "debris_skimmer") -- free-form string rather than an
 * enum so a new set piece is a data commit, same convention as
 * AquariumEvent.kind.
 */
export type AquariumSet = Prisma.AquariumSetModel
/**
 * Model AquariumDecor
 * cthulhuquarium/t-017: one purchased-and-placed decor object in one
 * Aquarium. Purely cosmetic (no economy effect, no slot cap) -- decor never
 * competes with setSlotsCap/sizeCap's two-pool balance. `kind` keys into
 * server/utils/aquariumEconomy.ts's DECOR_CATALOG, same free-form-string
 * convention as AquariumSet.kind and AquariumEvent.kind: a new decor item
 * is a data commit, not a migration. x/y are percentages (0-100) of the
 * canvas stage, not pixels, so placement survives a stage-size change
 * untouched. One row per placed instance -- buying two of the same kind is
 * two rows, not a quantity field, matching AquariumSet's per-instance shape
 * rather than AquariumStock's collection-of-individuals shape.
 */
export type AquariumDecor = Prisma.AquariumDecorModel
/**
 * Model AquariumCodexEntry
 * cthulhuquarium/t-032 item 4: the Ichthyonomicon. One row per user per
 * species ever bought or raised, whether or not currently owned -- survives
 * a sell. This is the record that makes t-030's rotating shop and sell-back
 * safe (rotation governs discovery, not access; anything in this table is
 * re-orderable). Append/update-only in spirit: t-030/t-031 create a row on
 * first acquisition and update bestStat* when a better individual is seen,
 * never delete one. See SYSTEMS.md "The shop rotates; the book is forever"
 * and "The Ichthyonomicon".
 */
export type AquariumCodexEntry = Prisma.AquariumCodexEntryModel
/**
 * Model Monster
 * cthulhuquarium/t-035: the bestiary's own model. Character is this site's
 * chattable-personality table -- people you can talk to, story NPCs -- and
 * fish/tank creatures have no dialogue, no personality, and no chat
 * surface. Reusing Character for them because its columns happened to fit
 * (species, class, backstory-as-quirks, the six Rarity stats) ignored what
 * the model MEANS, and the concrete cost was already paid once: fish
 * needed a capacity weight, `Character.size` was added for them, and when
 * that migration shipped unapplied it took every unselected
 * `prisma.character.findUnique()` down with it, including character-linked
 * art generation (kind-robots/t-071). Monster carries what the fish bible
 * (conductor projects/cthulhuquarium, external to this repo) actually
 * needs. Sharing survives unchanged -- `games` is the mechanism, not the
 * table, exactly as it was meant to be: a Monster tagged
 * "cthulhuquarium,ruler-hooked" is readable by both.
 * WIRED 2026-08-25 (t-038): AquariumStock.monsterId and
 * AquariumCodexEntry.monsterId now reference Monster. `Character.size` still
 * exists and is now dead weight -- dropping it needs the REVERSE deploy order
 * from an add (deploy the client that stops selecting it FIRST, then migrate),
 * so it is deliberately not in this change. Repointing those tables and dropping
 * Character.size are follow-on work, filed separately and kept out of this
 * migration so this one stays purely additive -- CREATE TABLE only, no
 * DROP, no rewrite of a table anything currently reads. See t-035's
 * roadmap note for the full ordering and why the drop specifically waits
 * on kind-robots/t-071 being resolved first.
 */
export type Monster = Prisma.MonsterModel
/**
 * Model AquariumEvent
 * Append-only audit trail for one Aquarium: feeds, purchases, rare
 * experiences, and anything else the future leaderboard/balance pass needs
 * to read back. `kind` is a free-form string tag rather than an enum so new
 * event types are a data commit, not a migration (cthulhuquarium/t-004's
 * data-driven-economy convention).
 */
export type AquariumEvent = Prisma.AquariumEventModel
